import 'dart:math' as math;
import 'package:flutter/material.dart';

/// Offline storybook artwork. One detailed painted diorama per chapter scene.
/// All illustrations are generated by Flutter Canvas: no emojis, network
/// images, fonts-as-pictures, external API keys or per-device downloads.
class LumoStoryScene extends StatelessWidget {
  const LumoStoryScene({
    super.key,
    required this.page,
    this.variant = 0,
    this.height = 226,
  });

  final int page;
  final int variant;
  final double height;

  @override
  Widget build(BuildContext context) {
    final scene = (page - 1).clamp(0, 11);
    return Semantics(
      label: _descriptions[scene],
      image: true,
      child: ClipRRect(
        borderRadius: BorderRadius.circular(24),
        child: SizedBox(
          width: double.infinity,
          height: height,
          child: CustomPaint(
            painter: _ScenePainter(scene, variant),
            size: Size.infinite,
          ),
        ),
      ),
    );
  }
}

const _descriptions = <String>[
  'Lumos leuchtende Bibliothek mit geheimnisvollem Buch',
  'Eine Botin übergibt Lumo einen versiegelten Brief',
  'Ein Brunnen mit roter Feder, grauem Stein und blauem Band',
  'Steinerne Treppe und drei Fundstücke im Abendlicht',
  'Das blaue Band weist den Weg zum ersten Geheimnis',
  'Ein stiller Garten mit Holzbank, Brunnen und Apfelbaum',
  'Eine alte Karte mit Kreis, Dreieck und Stern',
  'Eine geheime Tür im Garten mit drei leuchtenden Zeichen',
  'Vor der geheimen Tür leuchtet das Sternensymbol',
  'Ein verborgener Saal voller Bücher und einem Fundstück',
  'Ein rotes Notizbuch mit Zeichnung des Gartens',
  'Lumos gemütliche Leseecke bei warmem Lampenlicht',
];

class _ScenePainter extends CustomPainter {
  _ScenePainter(this.scene, this.variant);
  final int scene;
  final int variant;
  Canvas get _c => _canvas!;
  Canvas? _canvas;

  static const _navy = Color(0xFF07142F);
  static const _blue = Color(0xFF1975D9);
  static const _teal = Color(0xFF57E5EC);
  static const _gold = Color(0xFFFFD68E);
  static const _ink = Color(0xFF102A50);

  void _rect(Rect r, Color color, {double radius = 0, Color? end}) {
    _c.drawRRect(
      RRect.fromRectAndRadius(r, Radius.circular(radius)),
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [color, end ?? color],
        ).createShader(r),
    );
  }

  void _glow(Offset p, double radius, Color color, {double opacity = .55}) {
    _c.drawCircle(p, radius, Paint()
      ..shader = RadialGradient(colors: [
        color.withOpacity(opacity),
        color.withOpacity(0),
      ]).createShader(Rect.fromCircle(center: p, radius: radius)));
  }

  void _ellipse(Offset p, double rx, double ry, Color color) {
    _c.drawOval(Rect.fromCenter(center: p, width: rx * 2, height: ry * 2),
        Paint()..color = color);
  }

  void _poly(List<Offset> pts, Color color, {Color? end}) {
    final path = Path()..moveTo(pts.first.dx, pts.first.dy);
    for (final point in pts.skip(1)) { path.lineTo(point.dx, point.dy); }
    path.close();
    final rect = path.getBounds();
    _c.drawPath(path, Paint()
      ..shader = LinearGradient(
        begin: Alignment.topLeft, end: Alignment.bottomRight,
        colors: [color, end ?? color],
      ).createShader(rect));
  }

  void _line(Offset a, Offset b, Color color, double width) {
    _c.drawLine(a, b, Paint()
      ..color = color
      ..strokeWidth = width
      ..strokeCap = StrokeCap.round);
  }

  void _orb(double x, double y, double r, Color color) {
    _glow(Offset(x, y), r * 2.3, color, opacity: .32);
    final rect = Rect.fromCircle(center: Offset(x, y), radius: r);
    _c.drawCircle(Offset(x, y), r, Paint()
      ..shader = RadialGradient(
        center: const Alignment(-.4, -.55), radius: .95,
        colors: [Colors.white, color, color.withOpacity(.7), _navy],
        stops: const [0, .16, .72, 1],
      ).createShader(rect));
  }

  void _book(double x, double y, double w, double h,
      {Color cover = const Color(0xFFBF4264)}) {
    _poly([Offset(x, y + 4), Offset(x + w, y),
        Offset(x + w + 9, y + 5), Offset(x + 9, y + h + 5)],
        const Color(0xFFDCEEF1), end: const Color(0xFF7D9FBD));
    _poly([Offset(x, y), Offset(x + w, y - 4),
        Offset(x + w, y + h - 4), Offset(x, y + h)],
        cover, end: Color.lerp(cover, _navy, .5));
    _rect(Rect.fromLTWH(x + w * .12, y + h * .26,
        w * .7, math.max(2.0, h * .09)), _gold, radius: 1);
    _line(Offset(x + 4, y + 2), Offset(x + 4, y + h - 1),
        Colors.white.withOpacity(.34), 2);
  }

  void _bookshelf(double x, double y, double w, double h) {
    _rect(Rect.fromLTWH(x, y, w, h), const Color(0xFF452B55),
        end: const Color(0xFF15283C), radius: 4);
    for (int row = 0; row < 3; row++) {
      final shelfY = y + (row + 1) * h / 3 - 4;
      _rect(Rect.fromLTWH(x + 3, shelfY, w - 6, 6),
          const Color(0xFFAF7B55), end: const Color(0xFF573A40));
      for (int k = 0; k < 6; k++) {
        final bw = (w - 15) / 7;
        final bx = x + 7 + k * (bw + 2);
        final by = shelfY - h / 3 + 8 + ((k + row) % 3) * 3;
        _rect(Rect.fromLTWH(bx, by, bw, shelfY - by),
          <Color>[_blue, const Color(0xFFC76691),
              const Color(0xFF8DB9CC), const Color(0xFFCE995E)][(row + k) % 4],
          end: const Color(0xFF243B5A), radius: 2);
      }
    }
  }

  void _stoneSteps() {
    for (int i = 0; i < 5; i++) {
      final width = 150.0 + i * 36;
      final top = 118.0 + i * 21;
      final left = (390 - width) / 2;
      _poly([Offset(left + 20, top - 10), Offset(left + width - 20, top - 10),
          Offset(left + width, top + 5), Offset(left, top + 5)],
          const Color(0xFF8093A9), end: const Color(0xFFCFD4DD));
      _rect(Rect.fromLTWH(left, top + 5, width, 12),
          const Color(0xFF33476C), end: const Color(0xFF52698B), radius: 3);
    }
  }

  void _garden() {
    _glow(const Offset(285, 56), 116, const Color(0xFFFFDDA0));
    for (int i = 0; i < 7; i++) {
      final x = 22.0 + i * 61;
      final y = 93.0 + (i % 3) * 9;
      _line(Offset(x, y), Offset(x - 5, 187),
          const Color(0xFF324E51), 9);
      _orb(x, y, 22 + (i % 3) * 5, const Color(0xFF2B9877));
    }
    _poly([const Offset(0, 177), const Offset(110, 154),
        const Offset(265, 184), const Offset(390, 151),
        const Offset(390, 240), const Offset(0, 240)],
        const Color(0xFF275A55), end: const Color(0xFF182E4A));
  }

  void _fountain() {
    _ellipse(const Offset(200, 202), 90, 20, const Color(0xAA041122));
    _poly([const Offset(120, 180), const Offset(274, 180),
        const Offset(284, 193), const Offset(114, 193)],
        const Color(0xFF71889D), end: const Color(0xFF2A486E));
    _ellipse(const Offset(199, 178), 75, 17, const Color(0xFF67C5D8));
    _rect(const Rect.fromLTWH(187, 111, 23, 66),
        const Color(0xFF95B2C3), end: const Color(0xFF4A627A), radius: 4);
    _orb(199, 104, 17, const Color(0xFF8DE9FC));
    for (int i = -2; i <= 2; i++) {
      final x = 197.0 + i * 22;
      _line(const Offset(199, 107), Offset(x, 168),
        const Color(0x996CE7FF), 2);
    }
  }

  void _ribbon() {
    _poly([const Offset(233, 123), const Offset(284, 127),
        const Offset(300, 147), const Offset(277, 148),
        const Offset(259, 141), const Offset(226, 156)],
        const Color(0xFF93EEFF), end: const Color(0xFF0E5BDA));
    _glow(const Offset(269, 141), 55, _blue);
  }

  void _door({bool showStar = false}) {
    _glow(const Offset(196, 112), 98, _teal);
    _poly([const Offset(110, 216), const Offset(114, 79),
        const Offset(278, 79), const Offset(282, 216)],
        const Color(0xFFA9A8A5), end: const Color(0xFF37466E));
    _poly([const Offset(129, 217), const Offset(129, 98),
        const Offset(263, 98), const Offset(265, 217)],
        const Color(0xFF1A2D55), end: const Color(0xFF04111F));
    _rect(const Rect.fromLTWH(137, 108, 118, 109),
        const Color(0xFF274267), end: const Color(0xFF13233A), radius: 52);
    _orb(160, 132, 12, _blue);
    _orb(196, 132, 12, const Color(0xFFB39DF4));
    _orb(232, 132, 12, showStar ? _gold : _teal);
    if (showStar) {
      _glow(const Offset(232, 132), 50, _gold, opacity: .8);
      _star(const Offset(232, 132), 18, _gold);
    }
    _line(const Offset(195, 146), const Offset(195, 211),
        const Color(0xFF6A89B3), 2);
  }

  void _star(Offset p, double r, Color color) {
    final pts = <Offset>[];
    for (int i = 0; i < 10; i++) {
      final a = (math.pi * 2 * i / 10) - math.pi / 2;
      final rr = i.isEven ? r : r * .42;
      pts.add(Offset(p.dx + math.cos(a) * rr,
          p.dy + math.sin(a) * rr));
    }
    _poly(pts, color, end: const Color(0xFFF7A647));
  }

  void _recoveredObject() {
    // Final discovery must show the correct type of artifact for the book
    // the child actually selected, not a generic book on every storyline.
    final center = const Offset(194, 151);
    _glow(center, 64, _gold, opacity: .5);
    switch (variant % 12) {
      case 0: // star map
      case 5: // treasure drawing
        _poly(const [Offset(158, 116), Offset(220, 112),
          Offset(232, 179), Offset(150, 183)],
          const Color(0xFFFFEDC6), end: const Color(0xFFB69364));
        _star(const Offset(194, 150), 15, const Color(0xFFE8AB52));
        break;
      case 1: // children's keepsake book
      case 8: // herbarium
      case 9: // forest field guide
      case 10: // color atlas
        _book(168, 119, 53, 67,
          cover: variant == 8 ? const Color(0xFF3C9675)
              : variant == 10 ? const Color(0xFFC3578A)
              : const Color(0xFF754DA5));
        break;
      case 2: // moon lantern
        _line(const Offset(194, 112), const Offset(194, 124), _gold, 6);
        _orb(194, 154, 34, const Color(0xFFE6DCA5));
        _rect(const Rect.fromLTWH(177, 175, 33, 10), _gold, radius: 5);
        break;
      case 3: // cloud picture frame
        _rect(const Rect.fromLTWH(158, 117, 72, 67),
          const Color(0xFFC89D69), end: const Color(0xFF6C4A52), radius: 3);
        _rect(const Rect.fromLTWH(166, 125, 56, 51),
          const Color(0xFF4788C2), end: const Color(0xFFB6DCE7), radius: 1);
        for (int i = 0; i < 3; i++) {
          _ellipse(Offset(180 + 13.0 * i, 147), 14, 9,
            const Color(0xFFDFEFF8));
        }
        break;
      case 4: // musical key
      case 6: // compass
        _orb(194, 147, 27, const Color(0xFFCCA964));
        if (variant == 6) {
          _star(center, 19, _gold);
        } else {
          _line(const Offset(198, 116), const Offset(198, 162), _gold, 6);
          _ellipse(const Offset(185, 166), 14, 10, _gold);
        }
        break;
      case 7: // peace letter
        _poly(const [Offset(154, 125), Offset(226, 125),
          Offset(226, 182), Offset(154, 182)],
          const Color(0xFFFFEBD1), end: const Color(0xFFC5B4AC));
        _poly(const [Offset(154, 126), Offset(190, 157), Offset(226, 126)],
          const Color(0xFFFBEBD7), end: const Color(0xFFCFBBA7));
        _star(center, 10, const Color(0xFFCA6278));
        break;
      case 11: // merit badge
        _orb(194, 149, 26, _gold);
        _star(center, 20, const Color(0xFFEFBD67));
        _poly(const [Offset(179, 169), Offset(187, 196),
          Offset(196, 178), Offset(205, 196), Offset(212, 168)],
          const Color(0xFF88B6E8), end: const Color(0xFF31559B));
        break;
    }
  }

  @override
  void paint(Canvas canvas, Size size) {
    _canvas = canvas;
    canvas.save();
    canvas.scale(size.width / 390, size.height / 240);
    final sky = Rect.fromLTWH(0, 0, 390, 240);
    _rect(sky, <Color>[
      const Color(0xFF49346C), const Color(0xFF354970),
      const Color(0xFF386882), const Color(0xFF405080),
      const Color(0xFF2E587B), const Color(0xFF346870),
      const Color(0xFF3C376E), const Color(0xFF3D436B),
      const Color(0xFF414069), const Color(0xFF34315E),
      const Color(0xFF514073), const Color(0xFF373253),
    ][scene], end: _navy);
    for (int i = 0; i < 18; i++) {
      final x = (17 + i * 53 + scene * 19) % 390.0;
      final y = (9 + i * 41 + scene * 7) % 170.0;
      _ellipse(Offset(x, y), 1.0 + i % 3, 1.0 + i % 3,
          _gold.withOpacity(.18 + (i % 3) * .12));
    }
    _glow(const Offset(314, 33), 113, _gold, opacity: .34);
    _poly(const [Offset(0, 180), Offset(90, 150),
      Offset(195, 172), Offset(290, 144),
      Offset(390, 161), Offset(390, 240), Offset(0, 240)],
      const Color(0xFF35566F), end: const Color(0xFF111D39));
    switch (scene) {
      case 0:
        _bookshelf(12, 60, 91, 145);
        _bookshelf(290, 60, 91, 145);
        _poly(const [Offset(117, 209), Offset(153, 166),
          Offset(239, 165), Offset(268, 209)], const Color(0xFFA47B60),
          end: const Color(0xFF503D52));
        _glow(const Offset(195, 122), 85, _gold);
        _book(167, 120, 58, 43, cover: const Color(0xFF89456D));
        break;
      case 1:
        _bookshelf(6, 48, 93, 164);
        _poly(const [Offset(142, 209), Offset(150, 105),
          Offset(195, 78), Offset(236, 106), Offset(251, 210)],
          const Color(0xFF5F83AD), end: const Color(0xFF283D71));
        _orb(195, 82, 28, const Color(0xFFFFC49A));
        _poly(const [Offset(130, 119), Offset(265, 125),
          Offset(245, 190), Offset(147, 190)],
          const Color(0xFFFFF1D1), end: const Color(0xFFD5B58B));
        _star(const Offset(196, 150), 17, const Color(0xFFD44B6C));
        break;
      case 2:
        _garden(); _fountain();
        _orb(84, 196, 8, const Color(0xFFE4507E));
        _ribbon();
        break;
      case 3:
        _garden(); _stoneSteps(); _ribbon();
        break;
      case 4:
        _garden(); _stoneSteps(); _ribbon();
        _glow(const Offset(269, 128), 63, _teal);
        break;
      case 5:
        _garden(); _fountain();
        _rect(const Rect.fromLTWH(80, 174, 100, 10),
            const Color(0xFFCC9A64), end: const Color(0xFF653E42), radius: 4);
        _rect(const Rect.fromLTWH(89, 181, 7, 22), const Color(0xFF513E49));
        _rect(const Rect.fromLTWH(163, 181, 7, 22), const Color(0xFF513E49));
        break;
      case 6:
        _garden();
        _poly(const [Offset(87, 39), Offset(288, 53),
          Offset(301, 200), Offset(73, 201)],
          const Color(0xFFFFE5AF), end: const Color(0xFFB99A72));
        _line(const Offset(96, 79), const Offset(274, 93),
            const Color(0xFFA67754), 3);
        _orb(130, 119, 15, const Color(0xFF91BADA));
        _poly(const [Offset(185, 118), Offset(167, 147),
            Offset(200, 147)], const Color(0xFF7765B7));
        _star(const Offset(249, 133), 22, _gold);
        break;
      case 7:
        _garden(); _door();
        break;
      case 8:
        _garden(); _door(showStar: true);
        break;
      case 9:
        _bookshelf(14, 35, 115, 183);
        _bookshelf(267, 35, 111, 183);
        _poly(const [Offset(117, 195), Offset(275, 195),
          Offset(291, 211), Offset(102, 211)],
          const Color(0xFFA8825C), end: const Color(0xFF664A5C));
        _glow(const Offset(193, 150), 85, _gold);
        _recoveredObject();
        break;
      case 10:
        _garden();
        _poly(const [Offset(82, 174), Offset(260, 164),
          Offset(309, 213), Offset(47, 216)],
          const Color(0xFFA67657), end: const Color(0xFF59435D));
        _book(136, 133, 99, 59, cover: const Color(0xFFC34D64));
        _star(const Offset(188, 160), 16, _gold);
        break;
      case 11:
        _bookshelf(15, 60, 110, 159);
        _poly(const [Offset(107, 200), Offset(272, 199),
          Offset(302, 222), Offset(74, 222)],
          const Color(0xFFAF835F), end: const Color(0xFF5F4661));
        _book(141, 133, 87, 67, cover: const Color(0xFFC34D64));
        _rect(const Rect.fromLTWH(275, 92, 8, 110), _gold);
        _glow(const Offset(280, 83), 90, _gold, opacity: .55);
        _orb(281, 89, 24, _gold);
        break;
    }
    _rect(const Rect.fromLTWH(0, 229, 390, 11),
        Colors.black.withOpacity(.4));
    canvas.restore();
    _canvas = null;
  }

  @override
  bool shouldRepaint(covariant _ScenePainter oldDelegate) =>
      oldDelegate.scene != scene || oldDelegate.variant != variant;
}
